    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    // Calculate the score based on job type and available resources
    if job_cpu > job_ram {
        // CPU-heavy job
        let cpu_fit_ratio = node_residual_cpu as f64 / job_cpu as f64;
