        let ram_future_fit_ratio = (node_residual_ram + next_job_ram) as f64 / (job_ram + next_job_ram) as f64;
        score = 1.0 - ram_fit_ratio + imbalance_penalty * 4.0 + (1.0 - ram_future_fit_ratio) * 0.9;
