    if next_job_cpu > next_job_ram {
        score += (node_residual_cpu + next_job_cpu) as f64 / node_capacity_cpu as f64 * 0.6;
    } else {
        score += (node_residual_ram + next_job_ram) as f64 / node_capacity_ram as f64 * 0.6;
